  void NewTaskOrProject(){if(store.Data.Projects.Count==0){projectPicker.AddNew();return;}if(Dialogs.TaskEditor(this,store,null))taskPage=1;Refresh();}
  void Schedule(string id){if(ProjectTasks().Count==0){MessageBox.Show(this,"当前项目还没有任务，请先新建任务。","老秦进度管理软件");return;}var r=Dialogs.Schedule(this,store,id);if(r!=null){foreach(var s in r.Statuses)statusFilters.Add(s);if(chartStatusView!="全部状态"&&chartStatusView!="自选多状态"&&(statusFilters.Count!=1||!statusFilters.Contains(chartStatusView)))chartStatusView="自选多状态";viewStart=Model.Monday(r.Start);}Refresh();}
  void Export(){if(store.Data.Projects.Count==0){MessageBox.Show(this,"暂无项目，请先新建项目。全部数据仍可从左侧导出。","老秦进度管理软件");return;}Dialogs.Export(this,store,ChartTasks(),viewStart,viewStart.AddDays(days-1));}
  void Key(object sender,KeyEventArgs e){if((Keyboard.Modifiers&ModifierKeys.Control)==ModifierKeys.Control&&e.Key==System.Windows.Input.Key.N){NewTaskOrProject();e.Handled=true;}if((Keyboard.Modifiers&ModifierKeys.Control)==ModifierKeys.Control&&e.Key==System.Windows.Input.Key.E){Export();e.Handled=true;}}
 }
